success.beforeFullFileContent:
#!/usr/bin/perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $repo = $ARGV[0] || die "usage: $0 <repo>\n";
my $module = 'github.com/usememos/memos';

# symbol_key => { name, recv, pkg_path, pkg_name, file, line }
my %decls;
# pkg_path => { pkg_name, file_dir }
my %pkg_info;
# file => [ { alias, import_path } ]
my %file_imports;
# file => package name
my %file_pkg;

sub read_file {
    my ($path) = @_;
    open my $fh, '<', $path or return '';
    local $/;
    my $content = <$fh>;
    close $fh;
    return $content;
}

sub strip_comments {
    my ($s) = @_;
    # Remove block comments
    $s =~ s{/\*.*?\*/}{}gs;
    # Remove line comments (careful with strings - approximate)
    $s =~ s{//[^\n]*}{}g;
    return $s;
}

sub parse_go_file {
    my ($path, $content) = @_;
    my $pkg;
    if ($content =~ /\bpackage\s+(\w+)/) {
        $pkg = $1;
    }
    $file_pkg{$path} = $pkg // '';

    my @imports;
    if ($content =~ /\bimport\s*\((.*?)\)/s) {
        my $block = $1;
        while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            push @imports, { alias => $1 // '', path => $2 };
        }
    } elsif ($content =~ /\bimport\s+(?:(\w+)\s+)?"([^"]+)"/) {
        push @imports, { alias => $1 // '', path => $2 };
    }
    for my $imp (@imports) {
        if (!$imp->{alias}) {
            my @parts = split m{/}, $imp->{path};
            $imp->{alias} = $parts[-1];
            $imp->{alias} =~ s/-//g; # rough
        }
    }
    $file_imports{$path} = \@imports;

    # Determine if internal declaration file
    if ($path =~ m{^\Q$repo\E/internal/}) {
        my $dir = $path;
        $dir =~ s{/[^/]+$}{};
        my $rel = $dir;
        $rel =~ s{^\Q$repo\E/}{};
        my $pkg_path = "$module/$rel";
        $pkg_info{$pkg_path} = { pkg_name => $pkg, dir => $dir };

        my $clean = strip_comments($content);
        my @lines = split /\n/, $clean;
        for my $i (0 .. $#lines) {
            my $line = $lines[$i];
            next if $line =~ /^\s*func\s*\(/; # func type declaration
            if ($line =~ /^\s*func\s+(?:\(([^)]*)\)\s+)?(\w+)\s*\(/) {
                my ($recv, $name) = ($1 // '', $2);
                my $recv_type = '';
                if ($recv =~ /\*?\s*([\w.]+)/) {
                    $recv_type = $1;
                }
                my $key = symbol_key($pkg_path, $recv_type, $name);
                $decls{$key} = {
                    name => $name,
                    recv => $recv_type,
                    pkg_path => $pkg_path,
                    pkg_name => $pkg,
                    file => $path,
                    line => $i + 1,
                    call_sites => {},  # caller_file:line => 1
                };
            }
        }
    }
}

sub symbol_key {
    my ($pkg_path, $recv, $name) = @_;
    if ($recv) {
        return "$pkg_path|$recv|$name";
    }
    return "$pkg_path||$name";
}

# Build alias -> pkg_path map per file
sub file_alias_map {
    my ($path) = @_;
    my %map;
    for my $imp (@{ $file_imports{$path} // [] }) {
        $map{$imp->{alias}} = $imp->{path};
    }
    return %map;
}

# Resolve which internal symbol a call refers to
sub resolve_call {
    my ($caller_path, $qualifier, $name, $local_pkg_path) = @_;
    my %aliases = file_alias_map($caller_path);

    if (!$qualifier) {
        # unqualified - same package only
        my $key = symbol_key($local_pkg_path, '', $name);
        return $key if exists $decls{$key};
        # also try methods on types in same package - harder without type info
        for my $k (keys %decls) {
            next unless $decls{$k}{pkg_path} eq $local_pkg_path;
            next unless $decls{$k}{name} eq $name;
            return $k;
        }
        return '';
    }

    # qualified call: pkg.Func or recv.Method (recv is variable, not package)
    if (exists $aliases{$qualifier}) {
        my $import_path = $aliases{$qualifier};
        my $key = symbol_key($import_path, '', $name);
        return $key if exists $decls{$key};
    }

  # Method call: variable.Method - try to match any receiver type in internal
    for my $k (keys %decls) {
        next unless $decls{$k}{name} eq $name;
        # can't resolve receiver variable to type statically without type checker
    }
    return '';
}

sub caller_pkg_path {
    my ($path) = @_;
    return '' unless $path =~ m{^\Q$repo\E/(.+?)/[^/]+\.go$};
    my $dir = $1;
    return "$module/$dir";
}

sub count_calls_in_file {
    my ($path, $content) = @_;
    my $caller_pkg = caller_pkg_path($path);
    my %aliases = file_alias_map($path);

    # Build set of internal import paths for this file
    my %internal_imports; # alias -> full path
    for my $imp (@{ $file_imports{$path} // [] }) {
        if ($imp->{path} =~ m{^\Q$module\E/internal/}) {
            $internal_imports{$imp->{alias}} = $imp->{path};
        }
    }

    my $clean = strip_comments($content);
    my @lines = split /\n/, $clean;

    for my $i (0 .. $#lines) {
        my $line = $lines[$i];
        my $line_num = $i + 1;

        # Skip func declarations
        next if $line =~ /^\s*func\s+/;

        # Pattern 1: qualified package function call alias.Name(
        while ($line =~ /\b([a-zA-Z_]\w*)\.([A-Z]\w*)\s*\(/g) {
            my ($alias, $name) = ($1, $2);
            if (exists $internal_imports{$alias}) {
                my $pkg_path = $internal_imports{$alias};
                my $key = symbol_key($pkg_path, '', $name);
                if (exists $decls{$key}) {
                    # skip self-declaration line
                    next if $path eq $decls{$key}{file} && $line_num == $decls{$key}{line};
                    $decls{$key}{call_sites}{"$path:$line_num"} = 1;
                }
            }
        }

        # Pattern 2: unqualified calls in internal packages
        if ($caller_pkg && $caller_pkg =~ m{^\Q$module\E/internal/}) {
            while ($line =~ /\b([a-z]\w*)\s*\(/g) {
                my $name = $1;
                next if $name =~ /^(if|for|switch|return|func|go|defer|make|new|len|cap|append|delete|copy|close|panic|recover|print|println|map|chan|struct|interface|range|case|default)$/;
                my $key = symbol_key($caller_pkg, '', $name);
                if (exists $decls{$key}) {
                    next if $path eq $decls{$key}{file} && $line_num == $decls{$key}{line};
                    $decls{$key}{call_sites}{"$path:$line_num"} = 1;
                }
            }
            # exported/unexported starting with uppercase in same pkg
            while ($line =~ /\b([A-Z]\w*)\s*\(/g) {
                my $name = $1;
                next if $name =~ /^(Append|Bool|Byte|Close|Complex|Error|Float|Int|Make|New|Print|Printf|Println|Run|String|Uint|Unlock|Lock|Wait|Add|Done|Serve|Listen|Dial|Open|Read|Write|Seek|Stat|Mkdir|Remove|Copy|Parse|Format|Join|Split|Trim|Has|Get|Set|Is|To|From|With|Without)$/;
                my $key = symbol_key($caller_pkg, '', $name);
                if (exists $decls{$key}) {
                    next if $path eq $decls{$key}{file} && $line_num == $decls{$key}{line};
                    $decls{$key}{call_sites}{"$path:$line_num"} = 1;
                }
            }
        }

        # Pattern 3: method calls variable.Method(
        while ($line =~ /\b([a-zA-Z_]\w*)\.([A-Z]\w*)\s*\(/g) {
            my ($recv_var, $method) = ($1, $2);
            # skip if looks like package qualifier already handled
            next if exists $internal_imports{$recv_var};
            # match any method with this name in any internal package imported or same pkg
            for my $k (keys %decls) {
                next unless $decls{$k}{name} eq $method;
                # ambiguous - attribute to all matching methods in imported packages + same package
                my $pkg = $decls{$k}{pkg_path};
                my $in_scope = ($pkg eq $caller_pkg);
                if (!$in_scope) {
                    for my $alias (keys %internal_imports) {
                        if ($internal_imports{$alias} eq $pkg) { $in_scope = 1; last; }
                    }
                }
                if ($in_scope && $decls{$k}{recv}) {
                    next if $path eq $decls{$k}{file} && $line_num == $decls{$k}{line};
                    $decls{$k}{call_sites}{"$path:$line_num"} = 1;
                }
            }
        }
    }
}

# Collect all go files
my @go_files;
find(sub {
    return unless /\.go$/;
    push @go_files, $File::Find::name;
}, $repo);

for my $f (@go_files) {
    my $c = read_file($f);
    parse_go_file($f, $c);
}

for my $f (@go_files) {
    my $c = read_file($f);
    count_calls_in_file($f, $c);
}

# Rank by call site count
my @ranked = sort {
    scalar(keys %{$b->{call_sites}}) <=> scalar(keys %{$a->{call_sites}})
    || $a->{name} cmp $b->{name}
} values %decls;

print "TOP 30 BY DISTINCT CALL SITES:\n";
print "=" x 80, "\n";
my $n = 0;
for my $d (@ranked) {
    my $count = scalar keys %{$d->{call_sites}};
    next if $count == 0;
    $n++;
    last if $n > 30;
    my $sym = $d->{recv} ? "($d->{recv}).$d->{name}" : $d->{name};
    my $rel_file = $d->{file};
    $rel_file =~ s{^\Q$repo\E/}{};
    printf "%4d  %s  %s  %s:%d\n", $count, $d->{pkg_path}, $sym, $rel_file, $d->{line};
}

# Detail top symbol
if (@ranked && scalar(keys %{$ranked[0]{call_sites}}) > 0) {
    # find actual top with calls
    my ($top) = grep { scalar(keys %{$_->{call_sites}}) > 0 } @ranked;
    if ($top) {
        print "\nTOP SYMBOL DETAIL:\n";
        my $sym = $top->{recv} ? "($top->{recv}).$top->{name}" : $top->{name};
        print "Symbol: $sym\n";
        print "Package: $top->{pkg_path}\n";
        my $rel = $top->{file}; $rel =~ s{^\Q$repo\E/}{};
        print "Declaration: $rel:$top->{line}\n";
        print "Call sites: " . scalar(keys %{$top->{call_sites}}) . "\n";
        my @sites = sort keys %{$top->{call_sites}};
        my $show = @sites > 40 ? 40 : @sites;
        for my $i (0 .. $show - 1) {
            my $s = $sites[$i];
            $s =~ s{^\Q$repo\E/}{};
            print "  $s\n";
        }
        if (@sites > 40) {
            print "  ... and " . (@sites - 40) . " more\n";
        }
    }
}

# Also report total decls
print "\nTotal internal declarations: " . scalar(keys %decls) . "\n";

