#!/usr/bin/perl
use strict;
use warnings;

my $repo = $ARGV[0] || die "usage: $0 <repo>\n";
my $module = 'github.com/usememos/memos';

my %decls;       # key => { name, recv, pkg_path, file, line, exported }
my %pkg_aliases; # pkg_path => default alias (last path segment)
my %file_imports;
my %file_pkg_path;

sub read_file {
    my ($path) = @_;
    open my $fh, '<', $path or return '';
    local $/;
    return <$fh>;
}

sub strip_comments {
    my ($s) = @_;
    $s =~ s{/\*.*?\*/}{}gs;
    $s =~ s{//[^\n]*}{}g;
    return $s;
}

sub path_to_pkg {
    my ($path) = @_;
    return '' unless $path =~ m{^\Q$repo\E/(.+)/[^/]+\.go$};
    return "$module/$1";
}

sub default_alias {
    my ($import_path) = @_;
    my @p = split m{/}, $import_path;
    my $a = $p[-1];
    $a =~ s/-//g;
    return $a;
}

sub sym_key {
    my ($pkg, $recv, $name) = @_;
    return $recv ? "$pkg\x00$recv\x00$name" : "$pkg\x00\x00$name";
}

# --- phase 1: parse declarations in internal/ ---
my @go_files = split /\n/, `find '$repo' -name '*.go' -type f 2>/dev/null`;
chomp @go_files;

for my $f (@go_files) {
    my $content = read_file($f);
    my $pkg_path = path_to_pkg($f);
    $file_pkg_path{$f} = $pkg_path;

    my @imports;
    if ($content =~ /\bimport\s*\((.*?)\)/s) {
        while ($1 =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($alias, $path) = ($1, $2);
            $alias //= default_alias($path);
            push @imports, { alias => $alias, path => $path };
        }
    } elsif ($content =~ /\bimport\s+(?:(\w+)\s+)?"([^"]+)"/) {
        my ($alias, $path) = ($1, $2);
        $alias //= default_alias($path);
        push @imports, { alias => $alias, path => $path };
    }
    $file_imports{$f} = \@imports;

    next unless $f =~ m{^\Q$repo\E/internal/};
    my $clean = strip_comments($content);
    my @lines = split /\n/, $clean;
    for my $i (0 .. $#lines) {
        my $line = $lines[$i];
        next if $line =~ /^\s*func\s*\(/;
        if ($line =~ /^\s*func\s+(?:\(([^)]*)\)\s+)?(\w+)\s*\(/) {
            my ($recv, $name) = ($1 // '', $2);
            my $recv_type = '';
            if ($recv =~ /\*?\s*([\w.]+)/) { $recv_type = $1; }
            my $key = sym_key($pkg_path, $recv_type, $name);
            $decls{$key} = {
                name => $name, recv => $recv_type, pkg_path => $pkg_path,
                file => $f, line => $i + 1,
                exported => ($name =~ /^[A-Z]/),
                sites => {},
            };
            $pkg_aliases{$pkg_path} = default_alias($pkg_path) unless exists $pkg_aliases{$pkg_path};
        }
    }
}

# Build reverse map: for each internal pkg_path, all aliases used across repo
my %pkg_to_aliases;
for my $f (@go_files) {
    for my $imp (@{ $file_imports{$f} // [] }) {
        next unless $imp->{path} =~ m{^\Q$module\E/internal/};
        $pkg_to_aliases{$imp->{path}}{$imp->{alias}} = 1;
    }
    # same-package "alias" is empty string
    my $pp = $file_pkg_path{$f};
    if ($pp =~ m{^\Q$module\E/internal/}) {
        $pkg_to_aliases{$pp}{''} = 1;
    }
}

sub record_site {
    my ($key, $caller, $line) = @_;
    return unless exists $decls{$key};
    my $d = $decls{$key};
    return if $caller eq $d->{file} && $line == $d->{line};
    $d->{sites}{"$caller:$line"} = 1;
}

# --- phase 2: count calls ---
for my $f (@go_files) {
    my $content = read_file($f);
    my $caller_pkg = $file_pkg_path{$f};
    my $clean = strip_comments($content);
    my @lines = split /\n/, $clean;

    # alias -> import path for this file
    my %aliases;
    for my $imp (@{ $file_imports{$f} // [] }) {
        $aliases{$imp->{alias}} = $imp->{path};
    }

    for my $i (0 .. $#lines) {
        my $line = $lines[$i];
        my $ln = $i + 1;
        next if $line =~ /^\s*func\s+/;

        # Exported function: alias.Name( or pkg.Name( for same package exported
        while ($line =~ /\b([a-zA-Z_]\w*)\.([A-Z]\w*)\s*\(/g) {
            my ($alias, $name) = ($1, $2);
            my $target_pkg = $aliases{$alias} // '';
            if ($target_pkg =~ m{^\Q$module\E/internal/}) {
                my $key = sym_key($target_pkg, '', $name);
                record_site($key, $f, $ln) if exists $decls{$key};
            }
        }

        # Unexported package-level function in same internal package
        if ($caller_pkg =~ m{^\Q$module\E/internal/}) {
            while ($line =~ /\b([a-z][a-zA-Z0-9_]*)\s*\(/g) {
                my $name = $1;
                next if $name =~ /^(if|for|switch|return|func|go|defer|make|new|len|cap|append|delete|copy|close|panic|recover|print|println|map|chan|struct|interface|range|case|default|select|using)$/;
                my $key = sym_key($caller_pkg, '', $name);
                record_site($key, $f, $ln) if exists $decls{$key};
            }
        }

        # Method calls: recv.Method( where recv is lowercase (variable)
        while ($line =~ /\b([a-z][a-zA-Z0-9_]*)\.([A-Z]\w*)\s*\(/g) {
            my ($rv, $method) = ($1, $2);
            next if exists $aliases{$rv};  # package qualifier, already handled
            # Attribute to all methods with this name in packages imported by this file + same pkg
            for my $key (keys %decls) {
                my $d = $decls{$key};
                next unless $d->{name} eq $method && $d->{recv};
                my $pp = $d->{pkg_path};
                next unless $pp eq $caller_pkg || exists $aliases{ (grep { $aliases{$_} eq $pp } keys %aliases)[0] // '' };
                # check if pkg is in scope
                my $in_scope = ($pp eq $caller_pkg);
                if (!$in_scope) {
                    for my $a (keys %aliases) {
                        if ($aliases{$a} eq $pp) { $in_scope = 1; last; }
                    }
                }
                record_site($key, $f, $ln) if $in_scope;
            }
        }
    }
}

my @ranked = sort {
    scalar(keys %{$b->{sites}}) <=> scalar(keys %{$a->{sites}})
    || $a->{pkg_path} cmp $b->{pkg_path}
    || $a->{name} cmp $b->{name}
} values %decls;

print "TOP 25 (distinct call sites, all .go files):\n";
my $n = 0;
for my $d (@ranked) {
    my $c = scalar keys %{$d->{sites}};
    next unless $c > 0;
    $n++; last if $n > 25;
    my $sym = $d->{recv} ? "($d->{recv}).$d->{name}" : $d->{name}";
    my $rel = $d->{file}; $rel =~ s{^\Q$repo\E/}{};
