    $s =~ s{/\*.*?\*/}{}gs;
    $s =~ s{//[^\n]*}{}g;
    return $s;
}

sub path_to_pkg {
    my ($path) = @_;
    return '' unless $path =~ m{^\Q$repo\E/(.+)/[^/]+\.go$};
    return "$module/$1";
}

sub default_alias {
    my ($import_path) = @_;
    my @p = split m{/}, $import_path;
    my $a = $p[-1];
    $a =~ s/-//g;
    return $a;
}

sub sym_key {
    my ($pkg, $recv, $name) = @_;
    return $recv ? "$pkg\x00$recv\x00$name" : "$pkg\x00\x00$name";
}

